//! Synthetic legacy CRN fixtures, generated by `tools/fixtures/texture_crunch.py`.
//! The native fixture contains independently constructed BC blocks. The optional
//! pinned UnityPy fixture records `Texture2D.image` through a synthetic serialized
//! file, including Pillow's crop and flip. Missing oracle data is reported clearly.

use std::path::Path;

use serde_json::Value as J;
use sha2::{Digest, Sha256};
use unityrs_core::limits::Meter;
use unityrs_texture::{Format, decode, plan};

fn unhex(text: &str) -> Vec<u8> {
    assert_eq!(text.len() % 2, 0);
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap())
        .collect()
}

fn digest(bytes: &[u8]) -> String {
    use std::fmt::Write;
    Sha256::digest(bytes)
        .iter()
        .fold(String::new(), |mut text, byte| {
            write!(text, "{byte:02x}").unwrap();
            text
        })
}

fn number(value: &J) -> i32 {
    i32::try_from(value.as_i64().unwrap()).unwrap()
}

fn native() -> J {
    serde_json::from_str(include_str!("fixtures/crunch_native.json")).unwrap()
}

#[test]
fn synthetic_legacy_crunch_decodes_as_its_known_bc_blocks() {
    let doc = native();
    assert_eq!(doc["schema"], 1);
    let cases: Vec<_> = doc["cases"]
        .as_array()
        .unwrap()
        .iter()
        .chain(doc["truncated_cases"].as_array().unwrap())
        .chain(doc["data_size_cases"].as_array().unwrap())
        .chain(doc["edge_block_cases"].as_array().unwrap())
        .collect();
    assert_eq!(cases.len(), 23);
    for case in cases {
        let id = case["id"].as_str().unwrap();
        let format = Format::from_texture_format(number(&case["format"])).unwrap();
        let bc = if number(&case["format"]) == 28 {
            Format::Dxt1
        } else {
            Format::Dxt5
        };
        let data = unhex(case["data"]["hex"].as_str().unwrap());
        assert_eq!(digest(&data), case["data_sha256"].as_str().unwrap(), "{id}");
        let blocks = unhex(case["levels"][0]["blocks"].as_str().unwrap());
        let (width, height) = (number(&case["width"]), number(&case["height"]));
        let meter = Meter::unlimited();
        let got = decode(format, &data, width, height, &meter)
            .unwrap_or_else(|error| panic!("{id}: {error}"));
        let expected = decode(bc, &blocks, width, height, &Meter::unlimited()).unwrap();
        assert_eq!(got.mode(), expected.mode(), "{id}");
        assert_eq!(
            [got.width(), got.height()],
            [expected.width(), expected.height()],
            "{id}"
        );
        assert_eq!(got.pixels(), expected.pixels(), "{id}");
        // Planning is independent of CRN content; a valid stream can always use it.
        assert!(plan(format, data.len(), width, height).is_ok(), "{id}");
    }
}

#[test]
fn every_legacy_crunch_decode_is_the_oracle_image() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/crunch.json");
    let text = match std::fs::read_to_string(&path) {
        Ok(text) => text,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            eprintln!(
                "SKIP legacy Crunch UnityPy oracle replay: tests/fixtures/crunch.json is absent; \
                 generate with scripts/dev python tools/fixtures/texture_crunch.py"
            );
            return;
        }
        Err(error) => panic!("{}: {error}", path.display()),
    };
    let doc: J = serde_json::from_str(&text).unwrap();
    assert_eq!(doc["unitypy"], "1.25.2");
    assert_eq!(doc["pillow"], "9.5.0");
    assert_eq!(doc["texture2ddecoder"], "1.0.5");
    let native = native();
    let mut expected_cases: Vec<_> = native["cases"].as_array().unwrap().iter().collect();
    let mut cases: Vec<_> = doc["cases"].as_array().unwrap().iter().collect();
    assert_eq!(cases.len(), expected_cases.len());
    for group in ["truncated_cases", "data_size_cases", "edge_block_cases"] {
        if let Some(extra) = doc[group].as_array() {
            let expected = native[group].as_array().unwrap();
            assert_eq!(extra.len(), expected.len(), "{group}");
            cases.extend(extra);
            expected_cases.extend(expected);
        } else {
            eprintln!(
                "SKIP {group} Crunch UnityPy replay: regenerate crunch.json in the oracle container; native builder blocks are tested separately"
            );
        }
    }
    for (case, expected) in cases.into_iter().zip(expected_cases) {
        let id = case["id"].as_str().unwrap();
        for key in [
            "id",
            "format",
            "width",
            "height",
            "data",
            "levels",
            "data_sha256",
        ] {
            assert_eq!(case[key], expected[key], "{id}: {key}");
        }
        assert!(!unhex(case["file"].as_str().unwrap()).is_empty(), "{id}");
        let format = Format::from_texture_format(number(&case["format"])).unwrap();
        let data = unhex(case["data"]["hex"].as_str().unwrap());
        let image = decode(
            format,
            &data,
            number(&case["width"]),
            number(&case["height"]),
            &Meter::unlimited(),
        )
        .unwrap_or_else(|error| panic!("{id}: {error}"));
        assert_eq!(image.mode().name(), case["mode"].as_str().unwrap(), "{id}");
        assert_eq!(
            image.width(),
            u32::try_from(number(&case["size"][0])).unwrap(),
            "{id}"
        );
        assert_eq!(
            image.height(),
            u32::try_from(number(&case["size"][1])).unwrap(),
            "{id}"
        );
        assert_eq!(
            image.pixels(),
            unhex(case["pixels"].as_str().unwrap()),
            "{id}"
        );
        assert_eq!(
            digest(image.pixels()),
            case["sha256"].as_str().unwrap(),
            "{id}"
        );
    }
}
